export function refreshOnInstantNavigationUnlock() {
  if (process.env.__NEXT_EXPOSE_TESTING_API) {
    if (dispatch !== null) {
      dispatch({ type: ACTION_REFRESH, bypassCacheInvalidation: true })
    } else {
      window.location.reload()
